from dataclasses import dataclass
from datetime import datetime
from enum import StrEnum
from typing import Protocol
from uuid import UUID


class InitiationStatus(StrEnum):
    ACCEPTED = "accepted"
    REJECTED = "rejected"
    UNKNOWN = "unknown"


class VerificationStatus(StrEnum):
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    PENDING = "pending"
    UNKNOWN = "unknown"


@dataclass(frozen=True, slots=True)
class PaymentRequest:
    payment_id: UUID
    order_id: UUID
    amount: int
    currency: str
    expires_at: datetime

    # Generated by the backend, never accepted directly from the customer.
    callback_url: str


@dataclass(frozen=True, slots=True)
class InitiationResult:
    status: InitiationStatus
    authority: str | None = None
    redirect_url: str | None = None
    error_code: str = ""


@dataclass(frozen=True, slots=True)
class VerificationRequest:
    payment_id: UUID
    authority: str
    expected_amount: int
    currency: str


@dataclass(frozen=True, slots=True)
class VerificationResult:
    status: VerificationStatus

    # Populated from the gateway's server-side verification response.
    authority: str | None = None
    reference_id: str | None = None
    amount: int | None = None
    currency: str | None = None

    error_code: str = ""


class GatewayError(Exception):
    """Base exception for gateway adapter failures."""


class GatewayConfigurationError(GatewayError):
    """The adapter cannot run because its configuration is invalid."""


class GatewayUnavailableError(GatewayError):
    """
    The gateway could not be reached or its response was unusable.

    This does not prove that the payment failed.
    """


class PaymentGateway(Protocol):
    code: str

    def initiate(self, request: PaymentRequest) -> InitiationResult:
        """
        Create or recover a gateway payment session.

        Use payment_id as the merchant-side idempotency identifier
        when the provider supports it.

        An ambiguous response must not be reported as REJECTED.
        """
        ...

    def verify(
        self,
        request: VerificationRequest,
    ) -> VerificationResult:
        """
        Verify payment through a trusted server-side channel.

        Callback query parameters are not proof of payment.

        A successful result must contain the verified authority,
        reference ID, amount and currency.

        Verification must support repeated calls. A provider's
        'already verified' response counts as success only when
        the original transaction can be safely identified.

        If the provider cannot confirm the amount independently,
        leave amount unset. The service must then reconcile the
        transaction instead of automatically marking it paid.
        """
        ...